export const storyClosings=[{id:'share',label:'Compartir lo que ocurrió',text:'Sam escucha lo que Dani quiere contar, sin exigir explicar una emoción. Pueden tener razones distintas.'},{id:'later',label:'Dejar la historia aquí por hoy',text:'Dani y Sam dejan espacio para otra cosa. No necesitan volver mañana ni terminar una construcción.'}];
export function storyEnding(branch,action,closing){const b=Object.hasOwn(storyBranches,branch)?storyBranches[branch]:null,a=b?.options.find(o=>o.id===action),c=storyClosings.find(o=>o.id===closing);if(!a||!c)throw Error('Final desconocido');return {title:closing==='share'?'Un final para compartir':'Un final con espacio para parar',text:a.result+' '+c.text,question:'¿Qué cambiaría si eligieran otra opción? No hay un final mejor para todas las personas.'};}
